@Override // android.content.BroadcastReceiver
public void onReceive(Context context, Intent intent) {
    long currentDate = System.currentTimeMillis();
    Cursor c = context.getContentResolver().query(Notes.CONTENT_NOTE_URI, PROJECTION, "alert_date>? AND type=0", new String[]{String.valueOf(currentDate)}, null);
    if (c != null) {
        if (c.moveToFirst()) {
            do {
                long alertDate = c.getLong(1);
                Intent sender = new Intent(context, (Class<?>) AlarmReceiver.class);
                sender.setData(ContentUris.withAppendedId(Notes.CONTENT_NOTE_URI, c.getLong(0)));
                PendingIntent pendingIntent = PendingIntent.getBroadcast(context, 0, sender, 67108864);
                AlarmManager alermManager = (AlarmManager) context.getSystemService("alarm");
                alermManager.set(0, alertDate, pendingIntent);
            } while (c.moveToNext());
        }
        c.close();
    }
}
